import groovy.json.JsonSlurper
import org.apache.nifi.processor.io.InputStreamCallback
import javax.imageio.ImageIO
import javax.imageio.stream.MemoryCacheImageInputStream
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.util.Base64

class ImageValidationFailure extends RuntimeException {
    ImageValidationFailure(String code) {
        super(code)
    }
}

def flowFile = session.get()
if (flowFile == null) {
    return
}

final long MAX_JSON_BYTES = 20L * 1024 * 1024
final long MAX_IMAGE_BYTES = 10L * 1024 * 1024
final long MAX_PIXELS = 16_000_000L
final long MAX_BASE64_LENGTH = 4L * ((MAX_IMAGE_BYTES + 2L) / 3L)

def reject = { String code ->
    throw new ImageValidationFailure(code)
}

try {
    if (flowFile.getSize() > MAX_JSON_BYTES) {
        reject("JSON_TOO_LARGE")
    }

    String body = ""
    session.read(flowFile, { inputStream ->
        body = inputStream.getText(StandardCharsets.UTF_8.name())
    } as InputStreamCallback)

    def payload
    try {
        payload = new JsonSlurper().parseText(body)
    } catch (Exception ignored) {
        reject("INVALID_JSON")
    }

    if (!(payload instanceof Map)) {
        reject("INVALID_JSON_OBJECT")
    }

    def value = payload.get("image_base64")

    if (!(value instanceof String) || value.trim().isEmpty()) {
        reject("MISSING_IMAGE_BASE64")
    }

    String encoded = value

    if (encoded.length() > MAX_BASE64_LENGTH) {
        reject("IMAGE_TOO_LARGE")
    }

    // Standard Base64 only: no data URI, whitespace or URL-safe alphabet.
    if (encoded.length() % 4 != 0 ||
        !(encoded ==~ /[A-Za-z0-9+\/]*={0,2}/)) {
        reject("INVALID_BASE64")
    }

    byte[] imageBytes
    try {
        imageBytes = Base64.getDecoder().decode(encoded)
    } catch (IllegalArgumentException ignored) {
        reject("INVALID_BASE64")
    }

    if (Base64.getEncoder().encodeToString(imageBytes) != encoded) {
        reject("INVALID_BASE64")
    }

    if (imageBytes.length == 0) {
        reject("EMPTY_IMAGE")
    }

    if (imageBytes.length > MAX_IMAGE_BYTES) {
        reject("IMAGE_TOO_LARGE")
    }

    int width = 0
    int height = 0
    String format = ""

    def imageInput = new MemoryCacheImageInputStream(
        new ByteArrayInputStream(imageBytes)
    )
    def reader = null

    try {
        def readers = ImageIO.getImageReaders(imageInput)

        if (!readers.hasNext()) {
            reject("INVALID_OR_UNSUPPORTED_IMAGE")
        }

        reader = readers.next()
        format = reader.getFormatName().toUpperCase(Locale.ROOT)

        if (!(format in ["PNG", "JPEG", "JPG"])) {
            reject("UNSUPPORTED_IMAGE_FORMAT")
        }

        if (format == "JPG") {
            format = "JPEG"
        }

        reader.setInput(imageInput, false, false)
        width = reader.getWidth(0)
        height = reader.getHeight(0)

        if (width <= 0 || height <= 0) {
            reject("INVALID_IMAGE_DIMENSIONS")
        }

        if ((long) width * (long) height > MAX_PIXELS) {
            reject("IMAGE_TOO_MANY_PIXELS")
        }

        def decoded = reader.read(0)

        if (decoded == null ||
            decoded.getWidth() != width ||
            decoded.getHeight() != height) {
            reject("INVALID_IMAGE")
        }

        decoded.flush()
    } catch (IOException ignored) {
        reject("INVALID_IMAGE")
    } finally {
        if (reader != null) {
            reader.dispose()
        }
        imageInput.close()
    }

    String sha256 = MessageDigest.getInstance("SHA-256")
        .digest(imageBytes)
        .encodeHex()
        .toString()

    flowFile = session.removeAttribute(flowFile, "quarantine.reason")

    flowFile = session.putAllAttributes(flowFile, [
        "image.validation.status" : "VALID",
        "image.validation.version": "camera-image-v0.1",
        "image.format"            : format,
        "image.mime_type"         : format == "PNG"
            ? "image/png" : "image/jpeg",
        "image.width"             : Integer.toString(width),
        "image.height"            : Integer.toString(height),
        "image.size_bytes"        : Integer.toString(imageBytes.length),
        "image.sha256"            : sha256
    ])

    session.transfer(flowFile, REL_SUCCESS)

} catch (ImageValidationFailure failure) {
    flowFile = session.putAllAttributes(flowFile, [
        "image.validation.status" : "INVALID",
        "image.validation.version": "camera-image-v0.1",
        "quarantine.reason"       : failure.getMessage()
    ])

    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonSlurper
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.util.Base64

class MultipartValidationFailure extends RuntimeException {
    MultipartValidationFailure(String code) {
        super(code)
    }
}

def flowFile = session.get()
if (flowFile == null) {
    return
}

def reject = { String code ->
    throw new MultipartValidationFailure(code)
}

final long MAX_JSON_BYTES = 20L * 1024 * 1024
final long MAX_IMAGE_BYTES = 10L * 1024 * 1024

final String UUID_PATTERN =
    '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'

try {
    if (flowFile.getAttribute("image.validation.status") != "VALID") {
        reject("IMAGE_NOT_VALIDATED")
    }

    if (flowFile.getSize() > MAX_JSON_BYTES) {
        reject("JSON_TOO_LARGE")
    }

    String body = ""
    session.read(flowFile, { inputStream ->
        body = inputStream.getText(StandardCharsets.UTF_8.name())
    } as InputStreamCallback)

    def payload
    try {
        payload = new JsonSlurper().parseText(body)
    } catch (Exception ignored) {
        reject("INVALID_JSON")
    }

    if (!(payload instanceof Map)) {
        reject("INVALID_JSON_OBJECT")
    }

    def requestId = payload.get("request_id")
    def patientId = payload.get("patient_id")
    def modality = payload.get("modality")
    def eyeSide = payload.get("eye_side")
    def tenant = payload.tenant_id
    def clinic = payload.clinic_id
    def device = payload.device_id
    if (!(tenant instanceof String) || !(tenant ==~ UUID_PATTERN) ||
        (clinic != null && (!(clinic instanceof String) || !(clinic ==~ UUID_PATTERN))) ||
        !(device instanceof String) || !(device ==~ /^[A-Za-z0-9._:-]{1,128}$/) ||
        payload.version != 1) reject("INVALID_CAMERA_BINDING")
    def encoded = payload.get("image_base64")

    if (!(requestId instanceof String) ||
        !(requestId ==~ UUID_PATTERN)) {
        reject("INVALID_REQUEST_ID")
    }

    if (!(patientId instanceof String) ||
        !(patientId ==~ UUID_PATTERN)) {
        reject("INVALID_PATIENT_ID")
    }

    if (modality != "FUNDUS") {
        reject("UNSUPPORTED_MODALITY")
    }

    if (!(eyeSide in ["left", "right", "unknown"])) {
        reject("INVALID_EYE_SIDE")
    }

    if (!(encoded instanceof String) || encoded.isEmpty()) {
        reject("MISSING_IMAGE_BASE64")
    }

    byte[] imageBytes
    try {
        imageBytes = Base64.getDecoder().decode(encoded)
    } catch (IllegalArgumentException ignored) {
        reject("INVALID_BASE64")
    }

    if (imageBytes.length == 0 ||
        imageBytes.length > MAX_IMAGE_BYTES) {
        reject("INVALID_IMAGE_SIZE")
    }

    String actualHash = MessageDigest.getInstance("SHA-256")
        .digest(imageBytes)
        .encodeHex()
        .toString()

    if (actualHash != flowFile.getAttribute("image.sha256")) {
        reject("IMAGE_CHECKSUM_MISMATCH")
    }

    // Each device signs its own event. NiFi must not grant its service identity to arbitrary ingress metadata.
    def keys
    try { keys = new JsonSlurper().parseText(System.getenv("NIFI_CAMERA_DEVICE_KEYS_JSON") ?: "{}") }
    catch (Exception ignored) { reject("CAMERA_INGRESS_AUTH_UNAVAILABLE") }
    def secret = keys instanceof Map ? keys[device] : null
    def signature = payload.signature
    if (!(secret instanceof String) || secret.getBytes(StandardCharsets.UTF_8).length < 32 ||
        !(signature instanceof String) || !(signature ==~ /^[a-f0-9]{64}$/)) reject("CAMERA_INGRESS_DENIED")
    def signed = ["1", requestId, tenant, clinic ?: "", patientId, device, modality, eyeSide, actualHash].join("\n")
    def mac = javax.crypto.Mac.getInstance("HmacSHA256")
    mac.init(new javax.crypto.spec.SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"))
    if (!MessageDigest.isEqual(mac.doFinal(signed.getBytes(StandardCharsets.UTF_8)), signature.decodeHex()))
        reject("CAMERA_INGRESS_DENIED")

    String format = flowFile.getAttribute("image.format")

    if (!(format in ["JPEG", "PNG"])) {
        reject("UNSUPPORTED_IMAGE_FORMAT")
    }

    String mediaType = format == "PNG"
        ? "image/png" : "image/jpeg"

    String extension = format == "PNG" ? "png" : "jpg"
    String imageName = "image." + extension
    String boundary = "aura-" + flowFile.getAttribute("uuid")

    def multipart = new ByteArrayOutputStream()

    def appendText = { String text ->
        byte[] bytes = text.getBytes(StandardCharsets.UTF_8)
        multipart.write(bytes, 0, bytes.length)
    }

    def appendField = { String name, String value ->
        appendText("--" + boundary + "\r\n")
        appendText(
            "Content-Disposition: form-data; name=\"" +
            name + "\"\r\n"
        )
        appendText("\r\n" + value + "\r\n")
    }

    appendField("patientId", patientId)
    appendField("modality", modality)
    appendField("eyeSide", eyeSide)

    appendText("--" + boundary + "\r\n")
    appendText(
        "Content-Disposition: form-data; name=\"images\"; " +
        "filename=\"" + imageName + "\"\r\n"
    )
    appendText("Content-Type: " + mediaType + "\r\n\r\n")

    multipart.write(imageBytes, 0, imageBytes.length)
    appendText("\r\n--" + boundary + "--\r\n")

    byte[] preparedBody = multipart.toByteArray()

    flowFile = session.write(flowFile, { outputStream ->
        outputStream.write(preparedBody)
    } as OutputStreamCallback)

    flowFile = session.removeAttribute(flowFile, "quarantine.reason")

    flowFile = session.putAllAttributes(flowFile, [
        "mime.type"               :
            "multipart/form-data; boundary=" + boundary,
        "filename"                :
            flowFile.getAttribute("uuid") + ".multipart",
        "gateway.idempotency_key" : requestId.toLowerCase(java.util.Locale.ROOT),
        "camera.tenant_id"         : tenant,
        "camera.clinic_id"         : clinic ?: "",
        "camera.device_id"         : device,
        "gateway.correlation_id"  : requestId,
        "gateway.patient_id"      : patientId,
        "gateway.retry_count"     : "0",
        "gateway.payload.version": "analysis-multipart-v0.1",
        "gateway.payload.ready"   : "true"
    ])

    session.transfer(flowFile, REL_SUCCESS)

} catch (MultipartValidationFailure failure) {
    flowFile = session.putAllAttributes(flowFile, [
        "gateway.payload.ready": "false",
        "quarantine.reason"    : failure.getMessage()
    ])

    session.transfer(flowFile, REL_FAILURE)
}

import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import java.nio.charset.StandardCharsets
import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback

def ff = session.get()
if (ff == null) return

def post = { String url ->
    def conn = new URI(url).toURL().openConnection() as HttpURLConnection
    conn.instanceFollowRedirects = false
    conn.connectTimeout = 5000
    conn.readTimeout = 30000
    conn.requestMethod = 'POST'
    conn.doOutput = true
    conn
}
def readJson = { conn ->
    conn.inputStream.withCloseable { stream ->
        def bytes = stream.readNBytes(8193)
        if (bytes.length > 8192) throw new IOException('Response limit')
        new JsonSlurper().parseText(new String(bytes, StandardCharsets.UTF_8))
    }
}
def requiredOrigin = { String key ->
    def url = new URI(System.getenv(key) ?: '')
    if (!(url.scheme in ['http', 'https']) || !url.host || url.userInfo || url.query || url.fragment || !(url.path in ['', '/']))
        throw new IOException('Configured origin required')
    url.toString().replaceFirst('/$', '')
}
try {
    String secret = System.getenv('NIFI_CAMERA_CLIENT_SECRET')
    if (!secret) throw new IOException('Missing camera credentials')
    def issue = post(requiredOrigin('NIFI_CAMERA_IDENTITY_ORIGIN') + '/internal/v1/identity/service-tokens')
    String token
    try {
        issue.setRequestProperty('Content-Type', 'application/json')
        issue.outputStream.withCloseable { it.write(JsonOutput.toJson([
            clientId: System.getenv('NIFI_CAMERA_CLIENT_ID') ?: 'nifi-camera',
            clientSecret: secret, audience: 'aura-profile', scope: 'profile:camera'
        ]).getBytes(StandardCharsets.UTF_8)) }
        if (issue.responseCode != 200) throw new IOException('Camera token unavailable')
        def response = readJson(issue)
        if (response.tokenType != 'Bearer' || !(response.accessToken ==~ /[A-Za-z0-9_.-]{16,16384}/))
            throw new IOException('Invalid credential response')
        token = response.accessToken
    } finally { issue.disconnect() }

    def req = post(requiredOrigin('NIFI_CAMERA_GATEWAY_ORIGIN') + '/api/v1/analyses/camera' +
        (ff.getAttribute('camera.clinic_id') ? '?clinicContextId=' + ff.getAttribute('camera.clinic_id') : ''))
    try {
        String eventId = ff.getAttribute('gateway.idempotency_key')
        String hash = ff.getAttribute('image.sha256')
        String device = ff.getAttribute('camera.device_id')
        req.setRequestProperty('Authorization', 'Bearer ' + token)
        req.setRequestProperty('Content-Type', ff.getAttribute('mime.type'))
        req.setRequestProperty('Idempotency-Key', eventId)
        req.setRequestProperty('X-Tenant-Id', ff.getAttribute('camera.tenant_id'))
        req.setRequestProperty('X-Device-Id', device)
        req.setRequestProperty('X-Camera-SHA256', hash)
        req.setRequestProperty('X-Camera-Version', '1')
        req.setFixedLengthStreamingMode(ff.size)
        session.read(ff, { input -> req.outputStream.withCloseable { input.transferTo(it) } } as InputStreamCallback)
        int status = req.responseCode
        if (status == 202) {
            def receipt = readJson(req)
            if (receipt.requestId != eventId || receipt.deviceId != device || receipt.version != 1 ||
                receipt.imageSha256 != hash || receipt.imageCount != 1 || !(receipt.processingStatus in ['QUEUED', 'DUPLICATE']) ||
                !receipt.batchId || !receipt.analysisId || !receipt.sourceAcceptedAt)
                throw new IOException('Receipt did not match')
            ff = session.write(ff, { it.write(JsonOutput.toJson(receipt).getBytes(StandardCharsets.UTF_8)) } as OutputStreamCallback)
            ff = session.putAllAttributes(ff, ['mime.type':'application/json', 'filename':eventId + '.receipt.json',
                'camera.reporting.contract':'receipt-v1', 'camera.receipt.request_id': eventId,
                'camera.receipt.batch_id': receipt.batchId])
            session.transfer(ff, REL_SUCCESS)
        } else {
            String code = null
            if (status == 409 && req.errorStream != null)
                code = req.errorStream.withCloseable { stream ->
                    def bytes = stream.readNBytes(8193)
                    bytes.length <= 8192 ? new JsonSlurper().parseText(new String(bytes, StandardCharsets.UTF_8)).error?.code : null
                }
            boolean retry = status >= 500 || status in [401, 408, 429] || code == 'ERR_REQUEST_IN_PROGRESS'
            ff = session.putAttribute(ff, 'camera.delivery.retry', retry.toString())
            session.transfer(ff, REL_FAILURE)
        }
    } finally { req.disconnect() }
} catch (IOException | IllegalArgumentException | groovy.json.JsonException ignored) {
    ff = session.putAttribute(ff, 'camera.delivery.retry', 'true')
    session.transfer(ff, REL_FAILURE)
}
